import{_ as t,b as a,e as r,a8 as s}from"./chunks/framework.CD0vREyi.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"doc","docType":"api","unit":"GR32","entity":"TThreadPersistent","kind":"Class","declaration":"TThreadPersistent = class(TNotifiablePersistent)","inheritance":["TObject","TPersistent","TPlainInterfacedPersistent","TNotifiablePersistent","TThreadPersistent"],"summary":"Ancestor for TBitmap32 and core graphics objects, adding thread-safe locking mechanisms in addition to change notifications.","date":1787742964000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"api/GR32/TThreadPersistent/index.md","filePath":"api/GR32/TThreadPersistent/index.md","lastUpdated":1787742964000,"timestamp":1787742964000,"datetime":"2026-08-26T11:16:04.000Z","contributors":[{"commits":1,"email":"anders@melander.dk","name":"Anders Melander","avatar":"https://gravatar.com/avatar/a6bff52a3ccbe999ab6406528ffe48f1","maintainer":false,"links":[]}]}'),o={name:"api/GR32/TThreadPersistent/index.md"};function i(d,e,n,c,h,l){return a(),r("div",null,[...e[0]||(e[0]=[s('<h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p><code>TThreadPersistent</code> extends <code>TNotifiablePersistent</code> by providing critical-section locking methods (<code>Lock</code> and <code>Unlock</code>). This ensures thread-safe access to graphics surfaces and data structures across concurrent threads.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Inheriting from <code>TThreadPersistent</code> does not automatically make an object thread safe. <code>TThreadPersistent</code> merely provides a locking mechanism that you can employ to make your code thread safe.</p><p>Likewise, even though many Graphics32 classes inherit from <code>TThreadPersistent</code>, use of these classes are not inherently thread safe.</p></div><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to &quot;Constructors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Description</th></tr></thead><tbody><tr><td><a href="./Constructors/Create">Create</a></td><td>Initializes a new instance of <code>TThreadPersistent</code> and creates its internal critical section.</td></tr></tbody></table><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Description</th></tr></thead><tbody><tr><td><a href="./Methods/Lock">Lock</a></td><td>Acquires the internal critical section lock.</td></tr><tr><td><a href="./Methods/Unlock">Unlock</a></td><td>Releases the internal critical section lock.</td></tr></tbody></table><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Scope</th><th>Description</th></tr></thead><tbody><tr><td><a href="./Properties/LockCount">LockCount</a></td><td><code>Integer</code></td><td>Protected</td><td>Returns the current recursion level of critical section locks.</td></tr></tbody></table>',9)])])}const u=t(o,[["render",i]]);export{m as __pageData,u as default};
